void Anim2D::tryNextFrame()
{
	if (TheGameClient->getFrame() - m_lastFrameChange >= m_frameDuration) {
		switch (m_template->m_playMode) {
		case 1:
			if (m_frame < m_playEndFrame)
				setCurrentFrame(m_frame + 1);
			else
				setStatus(4);
			break;
		case 2:
			if (m_frame > m_playStartFrame)
				setCurrentFrame(m_frame - 1);
			else
				setStatus(4);
			break;
		case 3:
			if (m_frame == m_playEndFrame)
				setCurrentFrame(m_playStartFrame);
			else
				setCurrentFrame(m_frame + 1);
			break;
		case 4:
			if (m_frame > m_playStartFrame)
				setCurrentFrame(m_frame - 1);
			else
				setCurrentFrame(m_playEndFrame);
			break;
		case 5:
		case 6:
			if (m_status & 2) {
				if (m_frame == m_playStartFrame) {
					setCurrentFrame(m_frame + 1);
					clearStatus(2);
				} else {
					setCurrentFrame(m_frame - 1);
				}
			} else {
				if (m_frame == m_playEndFrame) {
					setCurrentFrame(m_frame - 1);
					setStatus(2);
				} else {
					setCurrentFrame(m_frame + 1);
				}
			}
			break;
		}
	}
}

