void Anim2DTemplate::parseNumImages(INI *ini, void *instance, void *store, const void *userData)
{
	unsigned int numFrames;
	INI::parseUnsignedInt(ini, instance, &numFrames, userData);
	Anim2DTemplate *animTemplate = (Anim2DTemplate *)instance;
	int minimumFrames = 1;
	if (numFrames < minimumFrames) {
		throw INIException(3, "Anim2DTemplate::parseNumImages - Invalid animation '%s', animations must have '%d' or more frames defined\n",
			animTemplate->m_name.str(), minimumFrames);
	}
	animTemplate->allocateImages((UnsignedShort)numFrames);
}

// FUNCTION: BFME2 0x002D7355 size=122 name=?storeImage@Anim2DTemplate@@QAEXPBVImage@@@Z evidence=N:ledger tier=A

void Anim2DTemplate::storeImage(const Image *image)
{
	if (image == 0)
		return;
	for (int frameIndex = 0; frameIndex < m_numFrames; ++frameIndex) {
		if (m_images[frameIndex] == 0) {
			m_images[frameIndex] = (Image *)image;
			return;
		}
	}
	throw INIException(3, "Anim2DTemplate::storeImage - Unable to store image '%s' into animation '%s' because the animation is setup to only support '%d' image frames\n",
		image->m_name.str(), m_name.str(), m_numFrames);
}

// FUNCTION: BFME2 0x002D73EC size=38 name=?parseImage@Anim2DTemplate@@KAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A

void Anim2DTemplate::parseImage(INI *ini, void *instance, void *store, const void *userData)
{
	const Image *image;
	INI::parseMappedImage(ini, instance, &image, userData);
	Anim2DTemplate *animTemplate = (Anim2DTemplate *)instance;
	animTemplate->storeImage(image);
}

// FUNCTION: BFME2 0x002D7412 size=282 name=?parseImageSequence@Anim2DTemplate@@KAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A

void Anim2DTemplate::parseImageSequence(INI *ini, void *instance, void *store, const void *userData)
{
	const Image *image;
	Anim2DTemplate *animTemplate = (Anim2DTemplate *)instance;
	if (animTemplate->getNumFrames() == 0)
		throw INIException(3, "Anim2DTemplate::parseImageSequence - You must specify the number of animation frames for animation '%s' *BEFORE* specifying the image sequence name\n", animTemplate->m_name.str());
	AsciiString imageBaseName = ini->getNextAsciiString();
	AsciiString imageName;
	for (int i = 0; i < animTemplate->getNumFrames(); ++i) {
		imageName.format("%s%03d", imageBaseName.str(), i);
		image = TheMappedImageCollection->findImageByName(imageName);
		if (image == 0)
			throw INIException(3, "Anim2DTemplate::parseImageSequence - Image '%s' not found for animation '%s'.  Check the number of images specified in INI and also make sure all the actual images exist.\n", imageName.str(), animTemplate->m_name.str());
		animTemplate->storeImage(image);
	}
}

// FUNCTION: BFME2 0x002D7554 size=114 name=?parseAnim2DDefinition@INI@@SAXPAV1@@Z evidence=N:ledger tier=A
void INI::parseAnim2DDefinition(INI *ini)
{
	AsciiString name;
	Anim2DTemplate *animTemplate;

	// read the name
	const char *c = ini->getNextToken();
	name.set(c);

	// Animations do not support overrides: a name already in use is left alone.
	if (!TheAnim2DCollection)
		return;

	animTemplate = TheAnim2DCollection->findTemplate(name);
	if (animTemplate == NULL)
		animTemplate = TheAnim2DCollection->newTemplate(name);
	else
		return;

	ini->initFromINI(animTemplate, Anim2DTemplate::s_anim2DFieldParseTable);
}

